function validateAndLog(masked, fullCard) {
  const cleanFull = fullCard.replace(/\D/g, '');
  if (cleanFull.length !== 16) throw new Error("Invalid card length");

  // Luhn Check
  let sum = 0;
  let isEven = false;
  for (let i = cleanFull.length - 1; i >= 0; i--) {
    let digit = parseInt(cleanFull[i]);
    if (isEven) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
    isEven = !isEven;
  }

  if (sum % 10 !== 0) throw new Error("Luhn check failed");

  // Verify prefix matches (4500)
  if (!masked.startsWith(cleanFull.substring(0, 4))) throw new Error("Prefix mismatch");

